package com.powercms.cms.delivery.navigation;
import com.powercms.cms.audit.AuditService;import com.powercms.cms.delivery.RenderDatasetCache;import com.powercms.common.error.BusinessException;import org.junit.jupiter.api.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
class UrlRewriteServiceTest {UrlRewriteRuleRepository repo=mock(UrlRewriteRuleRepository.class);UrlRewriteService service=new UrlRewriteService(repo,new RenderDatasetCache(20),mock(AuditService.class));UUID site=UUID.randomUUID();
 @Test void rejectsOpenRedirectTraversalAndDangerousRegex(){assertFalse(service.validate(site,null,"x","^(a+)+$","/ok",1).valid());assertFalse(service.validate(site,null,"x","^/x$","//evil.test",1).valid());assertFalse(service.validate(site,null,"x","^/x$","/../admin",1).valid());}
 @Test void appliesPriorityVariablesAndPreservesReserved(){var low=rule("low","^/old/(.*)$","/low/$1",1);var high=rule("high","^/old/(?<slug>[A-Za-z]+)$","/new/${slug}",9);when(repo.findBySiteIdOrderByPriorityDescNameAsc(site)).thenReturn(List.of(high,low));assertEquals("/new/story",service.rewrite(site,"/old/story",false));assertEquals("/api/users",service.rewrite(site,"/api/users",false));}
 @Test void detectsLoopAndHopLimit(){UrlRewriteRuleEntity a=rule("a","^/a$","/b",2),b=rule("b","^/b$","/a",1);when(repo.findBySiteIdOrderByPriorityDescNameAsc(site)).thenReturn(List.of(a,b));assertThrows(BusinessException.class,()->service.rewrite(site,"/a",true));}
 private UrlRewriteRuleEntity rule(String n,String p,String r,int priority){var x=new UrlRewriteRuleEntity();x.setSiteId(site);x.setName(n);x.setPattern(p);x.setReplacement(r);x.setPriority(priority);x.setStatus("ACTIVE");return x;}}
